const crypto = require('crypto');

// ---------- Secure Encryption Setup ----------
let ENCRYPTION_KEY;
try {
  const keyString = process.env.MED_ENCRYPTION_KEY || '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
  ENCRYPTION_KEY = Buffer.from(keyString.length === 64 ? keyString : '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef', 'hex');
} catch(e) {
  ENCRYPTION_KEY = Buffer.from('0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef', 'hex');
}

function decrypt(encryptedText) {
  if (!encryptedText) return '';
  try {
    const [ivHex, authTagHex, dataHex] = encryptedText.split(':');
    if (!ivHex || !authTagHex || !dataHex) return encryptedText;
    const iv = Buffer.from(ivHex, 'hex');
    const authTag = Buffer.from(authTagHex, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
    decipher.setAuthTag(authTag);
    let decrypted = decipher.update(dataHex, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  } catch (e) {
    return encryptedText;
  }
}

function sanitizeInput(text, maxLength = 300) {
  if (!text || typeof text !== 'string') return '';
  let clean = text
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '')
    .replace(/\{\{.*?\}\}/g, '')
    .trim();
  return clean.length > maxLength ? clean.substring(0, maxLength) : clean;
}

function isArabic(text) {
  return /[\u0600-\u06FF]/.test(text);
}

function simpleReply(chatId, text, buttons = null) {
  const payload = { chat_id: chatId, text, parse_mode: "HTML" };
  if (buttons) payload.reply_markup = { inline_keyboard: buttons };
  return [{ json: { send_type: "message", event_type: "simple_reply", chat_id: chatId, text_payload: payload } }];
}

const body = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();

if (!staticData._stats) staticData._stats = { totalQueries: 0, cacheHits: 0, visionScans: 0, ragQueries: 0, recallsChecked: 0 };

// ---------- Handle Callback Query ----------
if (body.callback_query) {
  const cq = body.callback_query;
  return [{
    json: {
      event_type: "callback",
      chat_id: cq.message.chat.id,
      callback_data: cq.data,
      callback_query_id: cq.id
    }
  }];
}

const msg = body.message;
if (!msg) return [];

const rawText = (msg.text || msg.caption || "").trim();
const text = sanitizeInput(rawText);
const chatId = msg.chat.id;
const userLang = isArabic(text) ? 'ar' : 'en';

// ---------- Rate Limiting ----------
const rateKey = `rate_${chatId}`;
if (staticData[rateKey] && (now - staticData[rateKey] < 1200)) {
  return simpleReply(chatId, userLang === 'ar' ? "⏳ <b>تنبيه:</b> يرجى الانتظار ثوانٍ قبل إرسال طلب جديد 🙏" : "⏳ <b>Please wait</b> a few seconds before sending a new request.");
}
staticData[rateKey] = now;

// ---------- Voice Note Handler ----------
if (msg.voice) {
  return simpleReply(chatId, userLang === 'ar' ? `🎙️ <b>تم استلام الرسالة الصوتية!</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n💡 <i>جاري معالجة الصوت وتحويله إلى استفسار طبي بـ Gemini Audio API...</i>` : `🎙️ <b>Voice Message Received!</b>\n\nProcessing audio query via Gemini Audio API...`);
}

// ---------- Document / PDF Handler ----------
if (msg.document) {
  const docName = msg.document.file_name || 'Medical Document';
  return simpleReply(chatId, `📄 <b>تم استلام المستند الطبي: ${docName}</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n💡 <i>جاري فحص التقارير والتحاليل الطبية بالذكاء الاصطناعي...</i>`);
}

// ---------- Commands ----------
if (text === "/start" || text === "القائمة الرئيسية") {
  return [{ json: { event_type: "start", chat_id: chatId, lang: userLang } }];
}

if (text === "/admin" || text === "/stats" || text === "إحصائياتي") {
  const stats = staticData._stats || {};
  const history = staticData[`history_${chatId}`] || [];
  const adminMsg = `📊 <b>لوحة تحكم MedSafety RAG v19.0 Enterprise Master</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n🔍 إجمالي البحث بالبوت: <b>${stats.totalQueries || 0}</b>\n📚 استعلامات الذكاء الاصطناعي RAG: <b>${stats.ragQueries || 0}</b>\n📷 فحص الروشتات Vision: <b>${stats.visionScans || 0}</b>\n🚨 فحص سحب الأدوية Recalls: <b>${stats.recallsChecked || 0}</b>\n📋 بحثك الشخصي: <b>${history.length} أدوية</b>\n🌐 المصادر: <b>OpenFDA + DailyMed + FDA Recalls Live + FAERS Live</b>\n🛡️ نظام التشفير: <b>AES-256-GCM</b>`;
  return simpleReply(chatId, adminMsg, [[{ text: "🏠 القائمة الرئيسية", callback_data: "menu_main" }]]);
}

// ---------- Renal eGFR Calculator (CKD-EPI 2021) ----------
if (text.startsWith("/egfr") || text.startsWith("كلى ")) {
  const parts = text.replace(/^(?:\/egfr|كلى)\s*/i, '').split(/[\s,،]+/);
  const age = parseInt(parts[0]);
  const gender = (parts[1] || 'male').toLowerCase();
  const scr = parseFloat(parts[2]);
  if (age > 0 && scr > 0) {
    let isFemale = gender.includes('f') || gender.includes('أنثى') || gender.includes('بنت');
    let k = isFemale ? 0.7 : 0.9;
    let alpha = isFemale ? -0.241 : -0.302;
    let minRatio = Math.min(scr / k, 1);
    let maxRatio = Math.max(scr / k, 1);
    let egfr = 142 * Math.pow(minRatio, alpha) * Math.pow(maxRatio, -1.200) * Math.pow(0.9938, age) * (isFemale ? 1.012 : 1.0);
    egfr = Math.round(egfr);
    let status = egfr >= 90 ? "وظائف كلى طبيعية 🟢" : egfr >= 60 ? "قصور كلوي خفيف 🟡" : egfr >= 30 ? "قصور كلوي متوسط 🟠" : "قصور كلوي شديد 🔴";
    let doseNote = egfr < 60 ? "⚠️ ينصح بتعديل جرعات أدوية مثل (Metformin, NSAIDs, Amoxicillin) حسب توصية الصيدلي." : "✅ الجرعات المعيارية آمنة للاستخدام.";
    return simpleReply(chatId, `🩺 <b>حاسبة معدل الترشيح الكلوي (eGFR - CKD-EPI 2021)</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n👤 العمر: <b>${age} سنة</b> | الجنس: <b>${isFemale ? 'أنثى' : 'ذكر'}</b>\n🧪 الكرياتينين: <b>${scr} mg/dL</b>\n📊 قيمة eGFR: <b>${egfr} mL/min/1.73m²</b>\n🏷️ التقييم: <b>${status}</b>\n\n${doseNote}`, [[{ text: "🏠 القائمة", callback_data: "menu_main" }]]);
  } else {
    return simpleReply(chatId, `🩺 <b>حاسبة eGFR الكلوية</b>\n\nاكتب البيانات كالتالي:\n<code>/egfr 45 female 1.1</code> (العمر ثم الجنس ثم الكرياتينين)`);
  }
}

// ---------- BMI Calculator ----------
if (text.startsWith("/bmi") || text.startsWith("وزن ")) {
  const parts = text.replace(/^(?:\/bmi|وزن)\s*/i, '').split(/[\s,،]+/);
  const weight = parseFloat(parts[0]);
  const heightCm = parseFloat(parts[1]);
  if (weight > 0 && heightCm > 0) {
    const heightM = heightCm / 100;
    const bmi = (weight / (heightM * heightM)).toFixed(1);
    let category = bmi < 18.5 ? "نقص وزن" : bmi < 25 ? "وزن مثالي 🟢" : bmi < 30 ? "زيادة وزن 🟡" : "سمنة 🔴";
    return simpleReply(chatId, `🧮 <b>حاسبة مؤشر كتلة الجسم (BMI)</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n⚖️ الوزن: <b>${weight} كجم</b> | الطول: <b>${heightCm} سم</b>\n📊 مؤشر BMI: <b>${bmi}</b>\n🏷️ التقييم: <b>${category}</b>\n\n💡 <i>تساعد في اختيار جرعة الأدوية المحسوبة بالوزن.</i>`, [[{ text: "🏠 القائمة", callback_data: "menu_main" }]]);
  } else {
    return simpleReply(chatId, `🧮 <b>حاسبة BMI</b>\n\nاكتب البيانات بالشكل التالي:\n<code>/bmi 75 175</code> (الوزن كجم ثم الطول سم)`);
  }
}

// ---------- Food Interactions ----------
if (text.startsWith("/food") || text.startsWith("أكل ") || text.startsWith("طعام ")) {
  const drugQuery = text.replace(/^(?:\/food|أكل|طعام)\s*/i, '').trim();
  let foodWarn = "⚠️ تجنب تناول عصير الجريب فروت مع أدوية الضغط والكوليسترول (مثل Lipitor) لتجنب مضاعفة التركيز بالسيروم. كما ينصح بفصل أدوية الحديد عن الشاي والقهوة بساعتين.";
  if (drugQuery.toLowerCase().includes('warfarin')) {
    foodWarn = "🥦 <b>تحذير خاص بالوارفارين (Warfarin):</b> ينصح بالثبات في تناول الخضروات الورقية الخضراء (السبانخ، البروكلي) لأن فيتامين K يقلل مفعول الدواء.";
  }
  return simpleReply(chatId, `🥗 <b>تداخلات الأغذية والأدوية (Drug-Food Interactions)</b>\n━━━━━━━━━━━━━━━━━━━━━\n\n🔍 الدواء: <b>${sanitizeInput(drugQuery || 'عام')}</b>\n\n${foodWarn}`, [[{ text: "🏠 القائمة", callback_data: "menu_main" }]]);
}

if (text === "/delete_data" || text === "حذف بياناتي") {
  return simpleReply(chatId, "⚠️ <b>تأكيد حذف البيانات الطبية</b>\n\nهل أنت متاكد من حذف ملفك الطبي وسجل استعلاماتك نهائياً؟", [
    [
      { text: "🗑️ نعم، احذف الكل", callback_data: "confirm_delete" },
      { text: "❌ إلغاء", callback_data: "menu_main" }
    ]
  ]);
}

if (text === "/history" || text === "سجلي") {
  return [{ json: { event_type: "callback", chat_id: chatId, callback_data: "history", callback_query_id: null } }];
}

if (text === "/trending" || text === "الأكثر بحثاً") {
  return [{ json: { event_type: "callback", chat_id: chatId, callback_data: "trending", callback_query_id: null } }];
}

// ---------- Dose Calculator ----------
if (text.startsWith("جرعة ") || text.startsWith("/dose")) {
  const cleanText = text.replace(/^(?:\/dose|جرعة)\s*/i, '');
  return [{
    json: {
      event_type: "dose_calc",
      chat_id: chatId,
      query: cleanText
    }
  }];
}

// ---------- Drug Comparison ----------
if (text.toLowerCase().includes(" vs ") || text.includes(" مقابل ") || text.includes(" ولا ") || text.startsWith("/compare")) {
  const cleanText = text.replace(/^\/compare\s*/i, '');
  const parts = cleanText.split(/\s+(?:vs|مقابل|ولا|,|،)\s+/i);
  if (parts.length >= 2) {
    return [{
      json: {
        event_type: "compare_drugs",
        chat_id: chatId,
        drug_a: sanitizeInput(parts[0]),
        drug_b: sanitizeInput(parts[1])
      }
    }];
  }
}

// ---------- Interaction Check ----------
if (text.startsWith("/interactions") || text.startsWith("تفاعلات ")) {
  const cleanText = text.replace(/^(?:\/interactions|تفاعلات)\s*/i, '');
  const drugs = cleanText.split(/[,،\n]+/).map(d => sanitizeInput(d)).filter(d => d.length > 1);
  if (drugs.length >= 2) {
    return [{
      json: {
        event_type: "interaction_check",
        chat_id: chatId,
        drug_list: drugs
      }
    }];
  }
}

// ---------- Profile Session Active ----------
const profileKey = `profile_${chatId}`;
if (staticData[profileKey] && staticData[profileKey].active) {
  return [{ json: { event_type: "profile_answer", chat_id: chatId, answer_text: text } }];
}

// ---------- Q&A Session Active ----------
const qaKey = `qa_${chatId}`;
if (staticData[qaKey] && staticData[qaKey].active) {
  if (now - (staticData[qaKey].startedAt || 0) > 600000) {
    delete staticData[qaKey];
  } else {
    return [{
      json: {
        event_type: "qa_question",
        chat_id: chatId,
        question_text: text,
        medication_name: staticData[qaKey].medication_name,
        rxcui: staticData[qaKey].rxcui,
        lang: userLang
      }
    }];
  }
}

// ---------- Prescription Image (Gemini Vision OCR) ----------
const hasPhoto = !!(msg.photo && msg.photo.length > 0);
const fileId = hasPhoto ? msg.photo[msg.photo.length - 1].file_id : null;

if (hasPhoto && fileId) {
  staticData._stats.visionScans = (staticData._stats.visionScans || 0) + 1;
  return [{
    json: {
      event_type: "vision_prescription",
      chat_id: chatId,
      telegram_file_id: fileId
    }
  }];
}

if (!text) {
  return simpleReply(chatId, "🤔 <b>لم أفهم طلبك جيداً</b>\n\nيرجى كتابة اسم الدواء، أو إرسال صورة الروشتة، أو الضغط على /start لرؤية القائمة الرئيسية.");
}

// ---------- Single Medication Query ----------
staticData._stats.totalQueries = (staticData._stats.totalQueries || 0) + 1;
const savedProfile = staticData[`saved_profile_${chatId}`];
let patientProfile = null;
if (savedProfile && savedProfile.answers) {
  try {
    patientProfile = {};
    for (const k in savedProfile.answers) {
      patientProfile[k] = decrypt(savedProfile.answers[k]);
    }
  } catch (e) {
    patientProfile = null;
  }
}

return [{
  json: {
    event_type: "medication_query",
    chat_id: chatId,
    medication_name: text,
    patient_profile: patientProfile,
    lang: userLang
  }
}];

const chatId = $json.chat_id;
const lang = $json.lang || 'ar';

const text = lang === 'en' ? `🏥 <b>Welcome to MedSafety RAG Master v19.0 Enterprise</b>
━━━━━━━━━━━━━━━━━━━━━

🩺 <b>AI & RAG Clinical Decision Support System</b>

<b>🔍 Complete Platform Services:</b>
┣ 💊 <b>Drug Search:</b> Type brand or generic name (e.g. Lipitor, Augmentin)
┣ 🧪 <b>Active Ingredient:</b> Auto-extracted from FDA Official Monograph
┣ 📷 <b>Prescription Scan:</b> Send prescription image for Gemini Vision OCR
┣ 🚨 <b>FDA Recall Alerts:</b> Live check on FDA drug recall database
┣ ⚖️ <b>Drug Comparison:</b> Type <code>Amoxicillin vs Augmentin</code>
┣ 🔄 <b>Drug Interactions:</b> Type <code>interactions Aspirin, Warfarin</code>
┣ 🥗 <b>Food Interactions:</b> Type <code>/food Lipitor</code>
┣ 🩺 <b>Renal eGFR:</b> <code>/egfr 45 female 1.1</code> (CKD-EPI 2021)
┣ 🧮 <b>BMI & Dose Calc:</b> <code>/bmi 75 175</code>
┗ 👤 <b>Encrypted Profile:</b> Custom safety warnings with AES-256-GCM

Select an option below or type a drug name 👇` : `🏥 <b>مرحباً بك في MedSafety RAG Master v19.0 Enterprise</b>
━━━━━━━━━━━━━━━━━━━━━

🩺 <b>نظام القرار الطبي القائم على الذكاء الاصطناعي وRAG</b>

<b>🔍 خدمات النظام الشاملة:</b>
┣ 💊 <b>فحص دواء:</b> اكتب أي اسم تجاري أو علمي (مثل: Lipitor, Augmentin)
┣ 🧪 <b>المادة الفعالة:</b> استخراج Active Ingredient تلقائياً من OpenFDA
┣ 📷 <b>قراءة الروشتة:</b> أرسل صورة الروشتة بفحص Gemini Vision
┣ 🚨 <b>سحب الأدوية:</b> فحص تلقائي حي لقرارات السحب الرسمية (FDA Recalls)
┣ ⚖️ <b>مقارنة أدوية:</b> اكتب <code>Amoxicillin vs Augmentin</code>
┣ 🔄 <b>تفاعلات الأدوية:</b> اكتب <code>تفاعلات Aspirin, Warfarin</code>
┣ 🥗 <b>تفاعلات الأغذية:</b> اكتب <code>/food Lipitor</code>
┣ 🩺 <b>وظائف الكلى:</b> <code>/egfr 45 female 1.1</code>
┣ 🧮 <b>حاسبة BMI والجرعات:</b> <code>/bmi 75 175</code>
┗ 👤 <b>الملف الطبي المشفّر:</b> لحفظ حالتك وتنبيهك تلقائياً

اختر من القائمة أو ابدأ بكتابة اسم الدواء مباشرة 👇`;

const buttons = [
  [
    { text: "👤 الملف الطبي المشفّر", callback_data: "profile_start" },
    { text: "📖 دليل الاستخدام", callback_data: "help" }
  ],
  [
    { text: "🏆 الأكثر بحثاً اليوم", callback_data: "trending" },
    { text: "📋 سجل استعلاماتي", callback_data: "history" }
  ],
  [
    { text: "📊 إحصائياتي", callback_data: "my_stats" }
  ]
];

return [{
  json: {
    send_type: "message",
    text_payload: {
      chat_id: chatId,
      text: text,
      parse_mode: "HTML",
      reply_markup: { inline_keyboard: buttons }
    }
  }
}];

// Strict Drug KB Lookup - Only triggers when medication_name is non-empty and length >= 2
if (!$json.medication_name || typeof $json.medication_name !== 'string' || $json.medication_name.trim().length < 2) {
  return []; // Stop execution completely if no medication name is provided!
}

const DRUG_INDEX = {
  "amoxicillin": { drug_id: "amoxicillin", drug_name: "Amoxicillin", active_ingredient: "Amoxicillin Trihydrate (أمكسيسيلين)", category: "Antibiotic / Penicillin", primary_indication: "Bacterial infections of ear, nose, throat, respiratory tract", dosage: "Adults: 500mg-875mg every 12 hours. Children: 25-45 mg/kg/day.", contraindications: "Severe penicillin or cephalosporin allergy", boxed_warning: "No boxed warning", patient_counseling: "Take at the start of a meal to enhance absorption and reduce stomach upset. Complete full prescribed course.", pregnancy: "Category B - Safe in pregnancy when clearly needed.", pediatric: "Safe for neonates, infants, and children with weight-based dosing.", image_url: "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=600&auto=format&fit=crop" },
  "aspirin": { drug_id: "aspirin", drug_name: "Aspirin", active_ingredient: "Acetylsalicylic Acid (حمض الأستيل ساليسليك)", category: "NSAID / Antiplatelet", primary_indication: "Pain relief, fever, antiplatelet therapy for cardiovascular protection", dosage: "81mg daily for heart protection, 325-650mg every 4-6 hours for pain.", contraindications: "Active GI bleeding, hemophilia, asthma with NSAID allergy", boxed_warning: "No boxed warning", patient_counseling: "Take with food or full glass of water. Avoid alcohol. Stop before surgery as directed by physician.", pregnancy: "Avoid in 3rd trimester (premature closure of ductus arteriosus).", pediatric: "Contraindicated in children < 19 with viral illness due to Reye Syndrome risk.", image_url: "https://images.unsplash.com/photo-1550572017-edd951aa8f72?w=600&auto=format&fit=crop" },
  "ibuprofen": { drug_id: "ibuprofen", drug_name: "Ibuprofen", active_ingredient: "Ibuprofen (إيبوبروفين)", category: "NSAID", primary_indication: "Pain, inflammation, fever", dosage: "200-400mg every 4-6 hours (Max 1200mg/day OTC, 3200mg RX).", contraindications: "Active peptic ulcer, severe heart failure, CABG surgery", boxed_warning: "Cardiovascular thrombotic events & Serious GI bleeding risk", patient_counseling: "Take with milk or meals to prevent stomach upset.", pregnancy: "Avoid at >= 20 weeks gestation (kidney problems in fetus).", pediatric: "Approved for children >= 6 months at 5-10 mg/kg every 6-8 hours.", image_url: "https://images.unsplash.com/photo-1471864190281-a93a3070b6de?w=600&auto=format&fit=crop" },
  "paracetamol": { drug_id: "paracetamol", drug_name: "Acetaminophen / Paracetamol", active_ingredient: "Paracetamol / Acetaminophen (باراسيتامول)", category: "Analgesic / Antipyretic", primary_indication: "Mild to moderate pain, fever reduction", dosage: "325-1000mg every 4-6 hours (Max 4000mg/day from all sources).", contraindications: "Severe hepatic impairment or severe active liver disease", boxed_warning: "Hepatotoxicity warning with overdosage (>4000mg/day)", patient_counseling: "Do not exceed maximum daily dose. Check ingredients of all cough/cold medicines to avoid double dosing.", pregnancy: "First-line safe analgesic in pregnancy at standard doses.", pediatric: "Safe for infants and children at 10-15 mg/kg per dose.", image_url: "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=600&auto=format&fit=crop" },
  "metformin": { drug_id: "metformin", drug_name: "Metformin", active_ingredient: "Metformin Hydrochloride (سيدوفاج / جلوكوفاج)", category: "Biguanide Anti-diabetic", primary_indication: "Type 2 Diabetes Mellitus", dosage: "Starting 500mg twice daily with meals, titrate to max 2550mg/day.", contraindications: "Severe renal impairment (eGFR < 30 mL/min), acute metabolic acidosis", boxed_warning: "Lactic Acidosis risk in renal failure, sepsis, or heavy alcohol use", patient_counseling: "Take with meals to reduce GI side effects (nausea, diarrhea).", pregnancy: "Often used in gestational diabetes under strict supervision.", pediatric: "Approved for children >= 10 years old.", image_url: "https://images.unsplash.com/photo-1576602976047-174e57a47881?w=600&auto=format&fit=crop" }
};

function truncate(str, len = 300) {
  if (!str) return '';
  const s = Array.isArray(str) ? str.join(' ') : String(str);
  return s.length > len ? s.substring(0, len) + '...' : s;
}

function normalize(name) {
  return (name || '').toLowerCase().trim().replace(/[^a-z0-9]/g, '');
}

const medNameInput = normalize($json.medication_name);
if (!medNameInput || medNameInput.length < 2) return [];

const patientProfile = $json.patient_profile || null;
let matchedDrug = null;

