const crypto = require('crypto');
let ENCRYPTION_KEY;
try {
  const keyString = process.env.MED_ENCRYPTION_KEY || '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef';
  ENCRYPTION_KEY = Buffer.from(keyString.length === 64 ? keyString : '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef', 'hex');
} catch(e) {
  ENCRYPTION_KEY = Buffer.from('0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef', 'hex');
}

function encrypt(text) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + authTag + ':' + encrypted;
}

